-- Lot 202 : payloads 31 a 60 sur 150.
--
-- Un texte propre a chaque IA. Les commandes etant neuves, aucune version
-- courante n'existe : rien n'est retire, tout est pose.

drop table if exists lot_v5_1_payloads;
create temporary table lot_v5_1_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-341","moteur":"chatgpt","payload":"[RaccourcIA — /musicreleasekit]\n\nMISSION\nDéclinez une sortie musicale en pochette, teaser, Story et bannière. Créer une identité de sortie originale puis la décliner sans modifier titres, noms ou visages.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quelle direction artistique doit porter la sortie ? Puis, uniquement si encore nécessaire : Quels formats faut-il produire en priorité ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer une identité de sortie originale puis la décliner sans modifier titres, noms ou visages. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nTitre, nom d’artiste, portrait, crédits fournis, couleurs et cohérence de campagne.\n\nÉVITER ET RESPONSABILITÉ\nFaux logo de label, date inventée, imitation d’une pochette existante, visage déformé et texte illisible. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"6e9ee60d208f29104dbc0b54d9430d110578e8e3a93e854f3d0ad788523f385d"},{"ref":"RCI-IMG-341","moteur":"claude","payload":"[RaccourcIA — /musicreleasekit]\n\nMISSION\nDéclinez une sortie musicale en pochette, teaser, Story et bannière. Créer une identité de sortie originale puis la décliner sans modifier titres, noms ou visages.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, consolide-les sans longue reformulation et vérifie les capacités réellement disponibles avant de produire. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quelle direction artistique doit porter la sortie ? Puis, uniquement si encore nécessaire : Quels formats faut-il produire en priorité ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer une identité de sortie originale puis la décliner sans modifier titres, noms ou visages. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nTitre, nom d’artiste, portrait, crédits fournis, couleurs et cohérence de campagne.\n\nÉVITER ET RESPONSABILITÉ\nFaux logo de label, date inventée, imitation d’une pochette existante, visage déformé et texte illisible. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"7fa6e69bb97659a196cd5a107035d867561b4fe0909bb116ed1f27cbf8a73e49"},{"ref":"RCI-IMG-341","moteur":"gemini","payload":"[RaccourcIA — /musicreleasekit]\n\nMISSION\nDéclinez une sortie musicale en pochette, teaser, Story et bannière. Créer une identité de sortie originale puis la décliner sans modifier titres, noms ou visages.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte et relie chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quelle direction artistique doit porter la sortie ? Puis, uniquement si encore nécessaire : Quels formats faut-il produire en priorité ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer une identité de sortie originale puis la décliner sans modifier titres, noms ou visages. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nTitre, nom d’artiste, portrait, crédits fournis, couleurs et cohérence de campagne.\n\nÉVITER ET RESPONSABILITÉ\nFaux logo de label, date inventée, imitation d’une pochette existante, visage déformé et texte illisible. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"17885e6dc61001eab81b0e653f156c7d50218275e0318ee3af705cda36feae67"},{"ref":"RCI-IMG-342","moteur":"chatgpt","payload":"[RaccourcIA — /profilelaunch]\n\nMISSION\nCréez les premiers visuels d’un nouveau compte professionnel ou créatif. Produire avatar, bannière et grille de trois couvertures avec cohérence de marque et lecture mobile.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Que doit comprendre une personne qui découvre le profil ? Puis, uniquement si encore nécessaire : Quels trois contenus faut-il mettre en avant au lancement ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nProduire avatar, bannière et grille de trois couvertures avec cohérence de marque et lecture mobile. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nNom exact, activité réelle, portrait, offre fournie et cohérence visuelle.\n\nÉVITER ET RESPONSABILITÉ\nCompétence inventée, faux résultat, promesse excessive, texte générique et mauvaise zone sûre. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"76c67c07234b160c8ac9372be4164e0c35e9be450bb0398322ee64c1fc65a67e"},{"ref":"RCI-IMG-342","moteur":"claude","payload":"[RaccourcIA — /profilelaunch]\n\nMISSION\nCréez